             FROM pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) a WHERE a.privilege_type = 'EXECUTE') g))) x(attr, want, got)
   WHERE x.attr = 'exists' OR p.oid IS NOT NULL
