      ('config', e.config, array_to_string(p.proconfig, ',')),
      ('returns', e.ret, pg_catalog.format_type(p.prorettype, NULL)),
      ('execute', e.exec, (SELECT string_agg(g.r, ',' ORDER BY g.r COLLATE "C") FROM (SELECT DISTINCT CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS r
             FROM pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) a WHERE a.privilege_type = 'EXECUTE') g))) x(attr, want, got)
   WHERE x.attr = 'exists' OR p.oid IS NOT NULL
